const app=document.querySelector('#app');
app.addEventListener('change',e=>{if(e.target.id==='registerAgree1'||e.target.id==='registerAgree2'){state[e.target.id==='registerAgree1'?'registerAgreement1':'registerAgreement2']=e.target.checked;render()}});
