const previewScreen=new URLSearchParams(location.search).get('screen');
const previewCase=new URLSearchParams(location.search).get('case');
const previewOverlay=new URLSearchParams(location.search).get('overlay');
let state={screen:meta[previewScreen]?previewScreen:'login',case:['unregisteredOneTap','unregisteredSms','unopenedOneTap','unopenedSms','openedOneTap','openedSms'].includes(previewCase)?previewCase:'unregisteredOneTap',agreed:false,overlay:['phonePicker','protocols','consentPrompt','newUser'].includes(previewOverlay)?previewOverlay:null,verifyStep:1,pending:null,protocolContext:'main',selectedPhone:'187****4324',codeCountdown:0,codeValue:'',smsCountdown:0,smsCodeValue:'',serviceAnswer:'',appleLinked:false,wechatAgreement:false,appleAgreement:false,backStack:[],verifyOrigin:'login',openingExit:'homeGuest'};
