function icon(name){const paths={phone:'<rect x="7" y="2.5" width="10" height="19" rx="2"/><path d="M10 18h4"/>',message:'<path d="M4 5.5h16v11H9l-5 4v-15Z"/><path d="M8 10h.01M12 10h.01M16 10h.01"/>',headset:'<path d="M4 13v-2a8 8 0 0 1 16 0v2"/><path d="M4 13h3v6H5a2 2 0 0 1-2-2v-2a2 2 0 0 1 1-2ZM20 13h-3v6h2a2 2 0 0 0 2-2v-2a2 2 0 0 0-1-2Z"/><path d="M17 19c0 1.5-2 2-5 2"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',eye:'<path d="M2 12s3.5-6 10-6 10 6 10 6-3.5 6-10 6S2 12 2 12Z"/><circle cx="12" cy="12" r="2.5"/>',swap:'<path d="m7 7-3 3 3 3M4 10h13M17 17l3-3-3-3M20 14H7"/>',chevron:'<path d="m9 18 6-6-6-6"/>',home:'<path d="m3 11 9-8 9 8v10h-6v-6H9v6H3Z"/>',chart:'<path d="M4 19V9M10 19V5M16 19v-8M22 19H2"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',asset:'<circle cx="12" cy="8" r="4"/><path d="M4 22a8 8 0 0 1 16 0"/>'};return `<svg class="ui-icon" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${paths[name]||paths.chevron}</svg>`}
function accountStatus(){return state.case.startsWith('unregistered')?'unregistered':state.case.startsWith('unopened')?'unopened':'opened'}
function completeLogin(){let status=accountStatus();if(status==='unregistered'){state.overlay='newUser';render()}else go(status==='unopened'?'homeUnopened':'homeLogged')}
function needsPasswordAfterOpening(){return accountStatus()==='unregistered'||['login','rememberedLogin','sms'].includes(state.verifyOrigin)}
function completeOpening(){go(needsPasswordAfterOpening()?'setPasswordAfterOpening':'assetsDone')}
function go(screen,opts={}){let requested=screen;if(screen==='verify')screen='opening';if(screen==='opening'&&state.screen!=='opening'){state.openingExit=['login','rememberedLogin','sms'].includes(state.screen)?'login':(accountStatus()==='unopened'||state.screen==='homeUnopened'?'homeUnopened':'homeGuest')}if(screen!==state.screen&&opts.track!==false){state.backStack.push({screen:state.screen,verifyStep:state.verifyStep,verifyOrigin:state.verifyOrigin});if(state.backStack.length>30)state.backStack.shift()}if(requested==='verify'&&state.screen!=='verify')state.verifyOrigin=state.screen;state.screen=screen;state.overlay=null;if(requested==='verify')state.verifyStep=opts.step||1;render()}
function back(fallback='login'){let previous=state.backStack.pop();if(previous){state.screen=previous.screen;state.verifyStep=previous.verifyStep;state.verifyOrigin=previous.verifyOrigin;state.overlay=null;render()}else go(fallback,{track:false})}
function head(title,back='login',showHelp=true){return `<div class="nav"><button class="back" data-back data-fallback="${back}">‹</button>${title}${showHelp?'<span class="help">客服</span>':''}</div>`}
function brand(){return `<div class="gt-logo"><span class="gt-mark"><img src="./assets/guotai-mark.png" alt="国泰基金标识"><small>GROUP</small></span><b>国泰基金</b></div>`}
function authTop(){return `<div class="auth-top"><button data-back data-fallback="login">‹</button><button class="service-btn" data-go="service" aria-label="智能客服">${icon('headset')}</button></div>${brand()}`}
function socials(){return `<div class="social-title">其他登录方式</div><div class="socials two-socials"><button data-go="wechatAuth" aria-label="微信"><img src="./assets/wechat.png" alt="微信登录"></button><button id="appleLogin" aria-label="Apple"><img src="./assets/apple.png" alt="Apple 登录"></button></div>`}
function bottom(active='home'){return `<nav class="bottom-nav">${[['home','首页','⌂'],['fund','基金','▧'],['learn','投顾','◇'],['assets','资产','♙']].map(([id,t,i])=>`<button class="${active===id?'active':''}" ${id==='assets'?'data-go="assetsGuest"':''}><i>${i}</i>${t}</button>`).join('')}</nav>`}
function login(){return `<section class="screen auth-bg one-tap-screen">${authTop()}<div class="login-hero brand-only-hero"><div class="phone-line"><strong>187****4324</strong><button class="switch-number" data-go="sms">⇄ 换号</button></div><div class="carrier">未注册手机号验证后将创建国泰用户账号<br>基金交易账户需另行开户</div></div><button class="account-link-left" data-go="account">账号密码登录</button><label class="agreements"><input id="agree" type="checkbox" ${state.agreed?'checked':''}><span>我已阅读并同意 <a data-protocol-context="main" data-overlay="protocols">《用户服务协议》《隐私政策》<br>《中国移动认证服务条款》</a></span></label><button class="primary" id="oneTap">本机号码一键登录</button>${socials()}<div class="activate-note">若您曾在银行或互联网等第三方合作平台购买过国泰基金，点击此处进行 <button data-go="verify">账户首次激活</button>，查看您的资产情况。</div></section>`}
function rememberedLogin(){return `<section class="screen auth-bg remembered-screen">${authTop()}<div class="auth-form remembered-form"><button class="remembered-phone" data-overlay="phonePicker">${icon('phone')}<b>${state.selectedPhone}</b>${icon('chevron')}</button><div class="remembered-code">${icon('message')}<input id="rememberedCode" value="${state.codeValue}" placeholder="请输入短信验证码" inputmode="numeric"><button id="rememberedGetCode" ${state.codeCountdown?'disabled':''}>${state.codeCountdown?`${state.codeCountdown}s后重试`:'获取验证码'}</button></div><button class="account-link-left" data-go="account">账号密码登录</button><label class="agreements auth-agree"><input id="rememberedAgree" type="checkbox"><span>我已阅读并同意 <a data-protocol-context="remembered" data-overlay="protocols">《用户服务协议》《隐私政策》<br>《中国移动认证服务条款》</a></span></label><button class="primary" id="rememberedLoginBtn">登录</button>${socials()}<div class="activate-note">若您曾在银行或互联网等第三方合作平台购买过国泰基金，点击此处进行 <button data-go="verify">账户首次激活</button>，查看您的资产情况。</div></div></section>`}
function sms(){return `<section class="screen auth-bg">${authTop()}<div class="auth-title"><h2>其他手机号登录</h2><p>未注册手机号验证后将创建国泰用户账号<br>基金交易账户需另行开户</p></div><div class="auth-form sms-form"><div class="line-input">${icon('phone')}<input value="18712344324" aria-label="手机号码" inputmode="tel"></div><div class="line-input">${icon('message')}<input id="smsCode" value="${state.smsCodeValue}" placeholder="请输入短信验证码" inputmode="numeric"><button id="smsGetCode" ${state.smsCountdown?'disabled':''}>${state.smsCountdown?`${state.smsCountdown}s后重试`:'获取验证码'}</button></div><label class="agreements auth-agree"><input id="smsAgree" type="checkbox"><span>我已阅读并同意 <a data-protocol-context="sms" data-overlay="protocols">《用户服务协议》《隐私政策》</a></span></label><button class="primary" id="smsLogin">登录</button><button class="account-link-right" data-go="account">账号密码登录</button>${socials()}<div class="activate-note compact-activation">若您曾在银行或互联网等第三方合作平台购买过国泰基金，点击此处进行 <button data-go="verify">账户首次激活</button>，查看您的资产情况。</div></div></section>`}
function account(){return `<section class="screen auth-bg">${authTop()}<div class="auth-title"><h2>账号密码登录</h2></div><div class="auth-form"><div class="plain-line">${icon('user')}<input id="accountInput" placeholder="请输入手机号/身份证号码/基金账号" aria-label="请输入手机号、身份证号码或基金账号"></div><div class="field-error" id="accountError"></div><div class="plain-line">${icon('lock')}<input id="passwordInput" type="password" placeholder="请输入登录密码/交易密码" aria-label="请输入登录密码或交易密码"><button class="eye-btn" id="eyeToggle">${icon('eye')}</button></div><div class="field-error" id="passwordError"></div><label class="agreements auth-agree"><input id="accountAgree" type="checkbox"><span>我已阅读并同意 <a data-protocol-context="account" data-overlay="protocols">《用户服务协议》《隐私政策》</a></span></label><button class="primary" id="accountLogin">登录</button><button class="account-register" data-go="register">注册</button><button class="forgot" data-go="forgotIdentity">忘记密码</button>${socials()}<p class="account-tip">账号支持绑定手机号／身份证号／基金账号<br>登录密码与交易密码均可直接输入</p></div></section>`}
