function service(){const answer=state.serviceAnswer?`<div class="service-reply">${state.serviceAnswer}</div>`:'';return `<section class="screen service-screen"><header class="service-head"><button data-back data-fallback="login">‹ 返回</button><b>国泰基金智能客服</b><span></span></header><div class="service-notice">🔊 我们的人工服务时间是工作日的8:30–17:00</div><div class="service-body"><div class="service-bubble">您好！我是您的智能助理小泰，很高兴为您服务，请问您想咨询什么问题？</div>${answer}<h3>猜你想问</h3><div class="guess-card">${['怎么卖出基金','国泰基金的联系方式和地址是什么','如何查询/修改持有基金的分红方式','直销和代销的概念','如何办理转托管','人工客服'].map(x=>`<button data-question="${x}">${x}</button>`).join('')}</div><div class="service-dots"><i></i><i></i><i></i><i></i></div></div><div class="service-compose"><div class="quick"><button data-question="人工客服">转人工</button><button>登录</button><button>注册</button><button>重置密码</button></div><div class="compose-line"><input placeholder="请输入您想咨询的问题"><button>➤</button></div></div></section>`}
