function register(){let ready=state.registerAgreement1&&state.registerAgreement2,phoneReady=(state.registerPhone||'').replace(/\D/g,'').length===11;return `<section class="screen register-screen">${head('注册','account',false)}<div class="register-form"><div class="register-row"><label>手机号码</label><input id="registerPhone" value="${state.registerPhone||''}" placeholder="请输入手机号码" inputmode="tel"></div><div class="register-row"><label>验证码</label><input id="registerCode" placeholder="请输入短信验证码" inputmode="numeric"><button id="registerGetCode" class="${phoneReady?'is-ready':''}" ${phoneReady?'':'disabled'}>发送验证码</button></div><div class="register-row recommender"><label>推荐人</label><input placeholder="请输入推荐人手机号（选填）" inputmode="tel"></div><div class="register-agreements"><label><input id="registerAgree1" type="checkbox" ${state.registerAgreement1?'checked':''}> 我已阅读并同意 <a data-protocol-context="register" data-overlay="protocols">《国泰基金 APP 用户协议》《个人投资者远程委托服务协议》《未成年人隐私政策》</a></label><label><input id="registerAgree2" type="checkbox" ${state.registerAgreement2?'checked':''}> 我已阅读并同意 <a data-protocol-context="register" data-overlay="protocols">《国泰基金隐私保护政策》</a></label></div><button class="register-confirm ${ready?'is-ready':''}" id="registerConfirm" ${ready?'':'disabled'}>确认</button></div></section>`}
function registerSuccess(){return `<section class="screen auth-bg success-v2"><div class="success-nav"><button data-back data-fallback="login">‹</button><b>注册成功</b></div>${brand()}<div class="success-main"><div class="success-check-v2">✓</div><p>已自动注册并登录</p><h2>请完成实名认证</h2><div class="success-desc">实名认证后可查看资产，并使用基金交易服务；开户完成后将设置登录密码并自动进入首页。</div><button class="primary" data-go="verify">去实名认证</button><button class="browse" data-go="homeGuest">暂不认证，先逛逛</button></div></section>`}
