function opening(){return `<section class="screen opening-screen"><iframe id="openingPrototype" title="开户流程" src="../../开户原型/开户与绑卡优化.html?entry=opening"></iframe></section>`}
function verify(){let s=state.verifyStep;if(s===1)return verifyIdentity();if(s===2)return verifyBank();return verifyMatch()}
function progress(n){return `<div class="verify-progress">${[['1','身份信息'],['2','银行卡核验'],['3','确认办理']].map((x,i)=>`<span class="${n>=i+1?'on':''}"><i>${n>i+1?'✓':x[0]}</i>${x[1]}</span>`).join('')}</div>`}
function verifyIdentity(){let note=accountStatus()==='unregistered'?'核验通过后将自动注册并建立登录态，再继续办理开户。':'系统将在证件识别后优先判断您是否已实名开户，避免重复办理。';return `<section class="screen">${head('账户首次激活',state.verifyOrigin,false)}${progress(1)}<div class="form"><div class="notice">为保障资产安全，姓名和证件信息仅用于识别实名开户状态与匹配候选账户。未完成银行卡及预留手机号核验前，不展示任何持仓数据。</div><div class="field"><label>姓名</label><input value="武家缘"></div><div class="field"><label>证件类型</label><select><option>居民身份证</option><option>其他证件</option></select></div><div class="field"><label>证件号码</label><input value="310***********4910"></div><button class="primary" id="activationIdentityNext">下一步</button><p class="flow-note">${note}</p></div></section>`}
function activationExisting(){return `<section class="screen auth-bg"><div class="success-nav"><button data-back data-fallback="login">‹</button><b>账户首次激活</b></div>${brand()}<div class="success-main"><div class="success-check-v2">✓</div><p>已识别实名信息</p><h2>您已拥有国泰基金账户</h2><div class="success-desc">无需重复激活或开户。您可以直接登录，或通过身份核验找回登录密码。</div><button class="primary" data-go="login">去登录</button><button class="browse" data-go="forgotIdentity">忘记密码</button></div></section>`}
function verifyBank(){return `<section class="screen">${head('银行卡安全核验','verify',false)}${progress(2)}<div class="form"><h2>验证本人银行卡</h2><p class="intro">用于确认本人身份与历史账户归属，不会发起扣款。</p><div class="field"><label>银行卡号</label><input value="6222 02•• •••• 6789"></div><div class="field"><label>银行预留手机号</label><input value="187 **** 4324"></div><div class="field"><label>短信验证码</label><div class="code-field"><input placeholder="请输入验证码"><button>获取验证码</button></div></div><label class="checkline"><input type="checkbox" checked> 本人同意进行银行卡鉴权并继续账户匹配</label><button class="primary" data-verify-step="3">完成核验</button></div></section>`}
function verifyMatch(){let isNew=accountStatus()==='unregistered';return `<section class="screen">${head('确认办理','verify',false)}${progress(3)}<div class="form"><h2>${isNew?'已自动注册并登录':'已完成本人核验'}</h2><p class="intro">${isNew?'平台账户已创建，将继续办理开户。':'已发现可关联的历史基金账户。请确认以下办理事项。'}</p><div class="summary-list"><div><span>实名信息</span><b>武*缘</b></div><div><span>${isNew?'平台账户':'发现历史账户'}</span><b>${isNew?'已自动注册':'1 个'}</b></div><div><span>持仓详情</span><b>确认后展示</b></div><div><span>直销账户</span><b>待开通</b></div></div><div class="notice">本次将连续完成：历史账户关联、风险测评及国泰直销账户开户。开户不会静默进行，下一页需阅读协议并主动确认。</div><button class="primary" data-go="consent">继续确认</button></div></section>`}
function consent(){return `<section class="screen">${head('关联与开户确认','verify',false)}<div class="form"><h2>最后一步</h2><p class="intro">请确认关联范围与开户协议。第三方份额仍由原销售渠道办理交易。</p><div class="summary-list"><div><span>账户关联</span><b>国泰历史基金账户</b></div><div><span>直销开户</span><b>同步开通</b></div><div><span>风险等级</span><b>稳健型</b></div></div><label class="checkline"><input id="openAgree1" type="checkbox"> 我已阅读并同意《账户关联授权书》</label><label class="checkline"><input id="openAgree2" type="checkbox"> 我已阅读并同意《基金账户开户协议》及《风险揭示书》</label><button class="primary" id="finishOpening">确认关联并开通</button><p class="microcopy">点击确认后，系统将完成历史账户关联和国泰直销账户开通。</p></div></section>`}
function setPasswordAfterOpening(){return `<section class="screen"><div class="nav"><button class="back" data-back data-fallback="login">‹</button>开户完成</div><div class="form"><h2>设置登录密码</h2><p class="intro">您的国泰基金交易账户已开通。设置登录密码后，可用于后续登录国泰基金 App。</p><div class="field"><label>登录密码</label><input id="openingPassword" type="password" placeholder="请输入登录密码"></div><div class="field"><label>确认登录密码</label><input id="openingPasswordConfirm" type="password" placeholder="请再次输入"></div><div class="notice">登录密码仅用于 App 登录；基金交易账户已完成开通，无需重复办理。</div><button class="primary" id="completePasswordLogin">完成并登录</button></div></section>`}
function assetsDone(){return `<section class="screen red-shell"><div class="topbar"><span class="identity">武*缘</span><h2>我的资产</h2><button>账单</button></div><div class="card asset-card"><div class="masked">实名及账户已开通 · 直销账户已开通</div><div class="amount">12,680.35</div><div class="yield">昨日收益　<b>+23.18</b></div><div class="asset-grid"><div>直销资产 <b>2,680.35</b></div><div>第三方持仓 <b>10,000.00</b></div></div><div class="holding"><span class="tag">支付宝 · 仅供查询</span><h4>国泰沪深300指数增强A</h4><div class="numbers"><span>持有金额<br><b>10,000.00</b></span><span>昨日收益<br><b style="color:var(--red)">+18.42</b></span></div><div class="note">数据以登记机构为准；申购、赎回等交易请返回原销售渠道办理。</div></div></div><div class="card menu-card"><button>交易查询</button><button>收益查询</button><button>资产分析</button><button>银行卡</button></div>${bottom('assets')}</section>`}
function protocolItems(){return ['main','remembered'].includes(state.protocolContext)?['用户服务协议','隐私政策','中国移动认证服务条款']:state.protocolContext==='opening'?['账户关联授权书','基金账户开户协议','风险揭示书']:['wechat','apple'].includes(state.protocolContext)?['国泰基金隐私保护政策','国泰基金APP用户协议']:['用户服务协议','隐私政策']}
function overlay(){if(state.overlay==='phonePicker')return `<div class="sheet-layer"><div class="sheet phone-picker"><div class="sheet-head"><b>选择登录手机号</b><button data-close>关闭</button></div><div class="phone-options"><button data-phone="187****4324"><span>${icon('phone')}<b>187****4324</b><small>最近使用</small></span>${state.selectedPhone==='187****4324'?'✓':''}</button><button data-phone="138****8899"><span>${icon('phone')}<b>138****8899</b><small>常用号码</small></span>${state.selectedPhone==='138****8899'?'✓':''}</button><button data-phone="156****2068"><span>${icon('phone')}<b>156****2068</b><small>常用号码</small></span>${state.selectedPhone==='156****2068'?'✓':''}</button><button id="useOtherPhone"><span>${icon('swap')}<b>使用其他手机号</b><small>输入新的手机号并验证</small></span>›</button></div></div></div>`;if(state.overlay==='protocols')return `<div class="sheet-layer"><div class="sheet protocol-sheet"><div class="sheet-head"><b>相关协议</b><button data-close>关闭</button></div><div class="sheet-list">${protocolItems().map(x=>`<button>${x} <small>›</small></button>`).join('')}</div></div></div>`;if(state.overlay==='consentPrompt')return `<div class="modal-layer"><div class="modal consent-modal"><h3>温馨提示</h3><p>请阅读并同意 ${protocolItems().map(x=>`《${x}》`).join('、')}</p><div class="modal-actions"><button data-close>不同意</button><button id="consentContinue">已阅读并同意</button></div></div></div>`;if(state.overlay==='newUser')return `<div class="modal-layer"><div class="modal register-modal"><h3>提示</h3><p>该手机号尚未注册，<br>将自动注册并进入国泰基金。</p><div class="modal-actions"><button data-close>暂不注册</button><button data-go="registerSuccess">确认并登录</button></div></div></div>`;return ''}
function render(){if(state.screen==='opening'){app.innerHTML=opening();document.querySelector('#stepBadge').textContent='06';document.querySelector('#stepTitle').textContent='开户注册';document.querySelector('#stepHint').textContent='身份证上传、实名信息、绑卡与密码设置';return}const views={login,rememberedLogin,sms,account,register,forgotIdentity,forgotMethod,forgotSms,resetPassword,resetSuccess,wechatAuth,wechatBind,wechatCode,appleAuth,appleBind,appleReturning,service,setPassword,setPasswordAfterOpening,registerSuccess,homeGuest,homeUnopened,homeLogged,assetsGuest,verify,activationExisting,consent,assetsDone};app.innerHTML=views[state.screen]()+overlay();let m=meta[state.screen]||meta.login;document.querySelector('#stepBadge').textContent=m[0];document.querySelector('#stepTitle').textContent=m[1];document.querySelector('#stepHint').textContent=m[2];document.querySelectorAll('#scenarioList button').forEach(b=>b.classList.toggle('active',b.dataset.case?b.dataset.case===state.case:b.dataset.go===state.screen));bind()}
function startCodeTimer(kind){const isRemembered=kind==='remembered',countKey=isRemembered?'codeCountdown':'smsCountdown',valueKey=isRemembered?'codeValue':'smsCodeValue',screen=isRemembered?'rememberedLogin':'sms';if(state[countKey]>0)return;state[countKey]=60;state[valueKey]='';render();setTimeout(()=>{state[valueKey]='682941';if(state.screen===screen)render()},650);const handle=setInterval(()=>{state[countKey]=Math.max(0,state[countKey]-1);if(state.screen===screen)render();if(state[countKey]===0)clearInterval(handle)},1000);if(isRemembered)rememberedTimer=handle;else smsTimer=handle}
function askConsent(context,pending){state.protocolContext=context;state.pending=pending;state.overlay='consentPrompt';render()}
function continuePending(){const p=state.pending;state.pending=null;if(['oneTap','remembered','sms'].includes(p)){state.agreed=true;completeLogin()}else if(p==='account'){completeLogin()}else if(p==='wechatBind'){go('wechatCode')}else if(p==='appleBind'){state.appleLinked=true;go('registerSuccess')}else if(p==='opening'){completeOpening()}}
function bind(){app.querySelectorAll('[data-go]').forEach(el=>el.onclick=()=>go(el.dataset.go));app.querySelectorAll('[data-back]').forEach(el=>el.onclick=()=>back(el.dataset.fallback));app.querySelectorAll('[data-overlay]').forEach(el=>el.onclick=e=>{e.preventDefault();state.protocolContext=el.dataset.protocolContext||state.protocolContext;state.overlay=el.dataset.overlay;render()});app.querySelectorAll('[data-close]').forEach(el=>el.onclick=()=>{state.overlay=null;state.pending=null;render()});app.querySelectorAll('[data-verify-step]').forEach(el=>el.onclick=()=>{state.backStack.push({screen:'verify',verifyStep:state.verifyStep,verifyOrigin:state.verifyOrigin});state.verifyStep=+el.dataset.verifyStep;render()});app.querySelectorAll('[data-question]').forEach(el=>el.onclick=()=>{state.serviceAnswer=el.dataset.question==='人工客服'?'正在为您转接人工客服，请稍候……':`您正在咨询“${el.dataset.question}”，可继续输入具体问题。`;render()});app.querySelectorAll('[data-phone]').forEach(el=>el.onclick=()=>{state.selectedPhone=el.dataset.phone;state.codeCountdown=0;state.codeValue='';if(rememberedTimer)clearInterval(rememberedTimer);state.overlay=null;render()});let activationNext=app.querySelector('#activationIdentityNext');if(activationNext)activationNext.onclick=()=>{if(accountStatus()==='opened')go('activationExisting');else{state.backStack.push({screen:'verify',verifyStep:state.verifyStep,verifyOrigin:state.verifyOrigin});state.verifyStep=2;render()}};let other=app.querySelector('#useOtherPhone');if(other)other.onclick=()=>go('sms');let getCode=app.querySelector('#rememberedGetCode');if(getCode)getCode.onclick=()=>startCodeTimer('remembered');let smsGetCode=app.querySelector('#smsGetCode');if(smsGetCode)smsGetCode.onclick=()=>startCodeTimer('sms');let wechatSend=app.querySelector('#wechatSend');if(wechatSend)wechatSend.onclick=()=>{if(!app.querySelector('#wechatAgree').checked)askConsent('wechat','wechatBind');else go('wechatCode')};let remembered=app.querySelector('#rememberedLoginBtn');if(remembered)remembered.onclick=()=>{if(!app.querySelector('#rememberedAgree').checked)askConsent('remembered','remembered');else completeLogin()};let agree=app.querySelector('#agree');if(agree)agree.onchange=()=>state.agreed=agree.checked;let tap=app.querySelector('#oneTap');if(tap)tap.onclick=()=>{if(!state.agreed)askConsent('main','oneTap');else completeLogin()};let smsLogin=app.querySelector('#smsLogin');if(smsLogin)smsLogin.onclick=()=>{if(!app.querySelector('#smsAgree').checked)askConsent('sms','sms');else completeLogin()};let eye=app.querySelector('#eyeToggle'),pwd=app.querySelector('#passwordInput');if(eye&&pwd)eye.onclick=()=>pwd.type=pwd.type==='password'?'text':'password';let login=app.querySelector('#accountLogin');if(login)login.onclick=()=>{let a=app.querySelector('#accountInput'),p=app.querySelector('#passwordInput'),ae=app.querySelector('#accountError'),pe=app.querySelector('#passwordError');let clean=a.value.replace(/\s/g,'');let defaultMasked=clean==='140107********4518';let accountOK=defaultMasked||/^\d{11}$/.test(clean)||/^\d{18}$/.test(clean)||clean.length>=6;let passwordOK=/^\d{6,20}$/.test(p.value);ae.textContent=accountOK?'':'请输入11位手机号、18位身份证号或有效基金账号';pe.textContent=passwordOK?'':'密码请输入6—20位数字';if(accountStatus()==='unregistered'){ae.textContent='该账号尚未注册，请使用手机号验证码登录';return}if(accountOK&&passwordOK){if(!app.querySelector('#accountAgree').checked)askConsent('account','account');else completeLogin()}};let finish=app.querySelector('#finishOpening');if(finish)finish.onclick=()=>{if(!app.querySelector('#openAgree1').checked||!app.querySelector('#openAgree2').checked)askConsent('opening','opening');else completeOpening()};let completePassword=app.querySelector('#completePasswordLogin');if(completePassword)completePassword.onclick=()=>go('homeLogged');let cc=app.querySelector('#consentContinue');if(cc)cc.onclick=continuePending}
const baseBind=bind;
bind=function(){baseBind();let appleLogin=app.querySelector('#appleLogin');if(appleLogin)appleLogin.onclick=()=>go(state.appleLinked?'appleReturning':'appleAuth');let wechatAgree=app.querySelector('#wechatAgree');if(wechatAgree)wechatAgree.onchange=()=>{state.wechatAgreement=wechatAgree.checked;render()};let wechatSend=app.querySelector('#wechatSend');if(wechatSend)wechatSend.onclick=()=>{if(state.wechatAgreement)go('wechatCode')};let wechatFinish=app.querySelector('#wechatFinish');if(wechatFinish)wechatFinish.onclick=()=>completeLogin();let appleAgree=app.querySelector('#appleAgree');if(appleAgree)appleAgree.onchange=()=>{state.appleAgreement=appleAgree.checked;render()};let appleComplete=app.querySelector('#appleComplete');if(appleComplete)appleComplete.onclick=()=>{if(state.appleAgreement){state.appleLinked=true;completeLogin()}};let appleReturningLogin=app.querySelector('#appleReturningLogin');if(appleReturningLogin)appleReturningLogin.onclick=()=>completeLogin();app.querySelectorAll('[data-reset-eye]').forEach(b=>b.onclick=()=>{let input=app.querySelector('#'+b.dataset.resetEye);input.type=input.type==='password'?'text':'password'})};
document.querySelectorAll('#scenarioList [data-go]').forEach(el=>el.addEventListener('click',()=>{state.case=el.dataset.case;state.agreed=false;go(el.dataset.go)}));
document.addEventListener('keydown',e=>{if(e.key.toLowerCase()==='r'){state={screen:'login',case:'unregisteredOneTap',agreed:false,overlay:null,verifyStep:1,pending:null,protocolContext:'main',selectedPhone:'187****4324',codeCountdown:0,codeValue:'',smsCountdown:0,smsCodeValue:'',serviceAnswer:'',appleLinked:false,wechatAgreement:false,appleAgreement:false,backStack:[],verifyOrigin:'login',openingExit:'homeGuest'};render()}});
window.addEventListener('message',event=>{if(event.data?.type==='opening-complete'){state.backStack=[];go('homeLogged',{track:false})}if(event.data?.type==='opening-exit'){state.backStack=[];go(state.openingExit,{track:false})}});
render();
